DELIMITER $$
CREATE TRIGGER `tg_devices_insert` BEFORE INSERT ON `devices` FOR EACH ROW BEGIN
    DECLARE next_val INT;
    SELECT AUTO_INCREMENT INTO next_val 
    FROM information_schema.TABLES 
    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'devices';
    SET NEW.device_id = CONCAT('dev_', LPAD(next_val, 4, '0'));
END
$$
